fn read_windows_resources(&mut self,cx:&mut Context<Self>) {
    if !passive_read_allowed(self.busy,self.uncertain,
        self.review.as_ref().is_some_and(Review::needs_approval)){
        self.developer_status="Finish or cancel the pending Host decision first".into();cx.notify();return;
    }
    self.busy=true;
    self.developer_status="Reading native resource counters through Host…".into();cx.notify();
    let source_epoch=self.source_epoch;
    let task=cx.background_executor().spawn(async move {control::read_native_resources()});
    cx.spawn(async move |this,cx|{
        let result=task.await;
        let _=this.update(cx,|view,cx|{
            view.busy=false;
            if view.source_epoch!=source_epoch{
                view.developer_status="Resource observation invalidated by a Host state change".into();cx.notify();return;
            }
            view.developer_status=match result{
                Ok(v) if v["status"]=="unsupported"=>"Native resource probe unsupported".into(),
                Ok(v)=>{
                    let d=&v["data"];
                    match (d["memoryTotalBytes"].as_u64(),d["memoryAvailableBytes"].as_u64()){
                        (Some(t),Some(a)) if t>0&&a<=t=>{
                            let cpu=d["cpuBusyBasisPoints"].as_u64().filter(|n|*n<=10000)
                                .map(|n|format!("{:.1}% (calling processor group)",n as f64/100.0))
                                .unwrap_or_else(||"unavailable".into());
                            format!("RAM {:.2}/{:.2} GiB used · CPU {} · native Host observation",
                              (t-a) as f64/1073741824.0,t as f64/1073741824.0,cpu)
                        },
                        _=>"Invalid native resource projection".into()
                    }
                },
                Err(e)=>format!("Native resource read unavailable: {}",e.label())
            };cx.notify();
        });
    }).detach();
