/// Local owner-approved PTY attachment. No public endpoint or second executor.
/// The caller must drain output on a separate thread before waiting/closing.
pub(super) fn spawn_console(exe:&Path,cwd:&Path,args:&[OsString],environment:&[(OsString,OsString)],size:Size)
->io::Result<(Self,File,File)>{
 let app=terminated(exe.as_os_str())?;let directory=terminated(cwd.as_os_str())?;
 let mut cmd=Vec::new();quote(exe.as_os_str(),&mut cmd)?;for arg in args{cmd.push(32);quote(arg,&mut cmd)?;}
 if cmd.len()>=32767{return Err(invalid());}cmd.push(0);
 let env=env_block(environment)?;
 let (console,input,output)=Console::create(size).map_err(|_|io::Error::other("pseudoconsole unavailable"))?;
 unsafe{
  let h=CreateJobObjectW(null(),null());if h.is_null(){return Err(io::Error::last_os_error());}
  let job=own(h);let mut limits:JOBOBJECT_EXTENDED_LIMIT_INFORMATION=zeroed();
  limits.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
  ok(SetInformationJobObject(raw(&job),JobObjectExtendedLimitInformation,(&limits as *const JOBOBJECT_EXTENDED_LIMIT_INFORMATION).cast(),size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>()as u32))?;
  let jobs=[raw(&job)];let mut attrs=Attributes::new()?;
  attrs.set(PROC_THREAD_ATTRIBUTE_JOB_LIST as usize,&jobs)?;
  attrs.set_console(&console)?;
  let mut si:STARTUPINFOEXW=zeroed();si.StartupInfo.cb=size_of::<STARTUPINFOEXW>()as u32;si.lpAttributeList=attrs.ptr;
  let mut pi:PROCESS_INFORMATION=zeroed();
  // Console supplies its own streams. No std-handle inheritance, no
  // CREATE_NO_WINDOW, no breakaway or uncontained fallback.
  ok(CreateProcessW(app.as_ptr(),cmd.as_mut_ptr(),null(),null(),0,
   EXTENDED_STARTUPINFO_PRESENT|CREATE_UNICODE_ENVIRONMENT,
   env.as_ptr().cast(),directory.as_ptr(),&si.StartupInfo,&mut pi))?;
  let root=own(pi.hProcess);let _thread=own(pi.hThread);
  Ok((Self{job,root,console:Some(console)},input,output))
 }
}
